<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Domain;
final class RulesEngine{public function applicableQuestions(ApplicabilityContext $c,array $qs):array{return array_values(array_map(function($q)use($c){$q['question_text']=$this->resolveQuestionText($c,$q);return$q;},array_filter($qs,fn($q)=>$this->isApplicable($c,$q))));}public function isApplicable(ApplicabilityContext $c,array $q):bool{$k=$q['question_key'];$p=$c->profile;if(in_array($k,['M04_CONSULTATION','R03_HIGHER_NEEDS','T01_INDUCTION','T02_TRAINING_SUPERVISION','T03_TRAINING_RECORDS','A01_FIRST_AID','A02_INCIDENTS','A03_RIDDOR'],true))return$c->hasEmployees();if(str_starts_with($k,'F'))return$c->hasFireResponsibility();if(str_starts_with($k,'L'))return$c->hasWaterResponsibility();if(str_starts_with($k,'AS'))return$c->hasAsbestosResponsibility()&&($k!=='AS04_ASBESTOS_INTRUSIVE'||in_array($p['intrusive_work_planned'],['yes','not_sure'],true));$flags=['C01_COSHH'=>'hazardous_substances','D01_DSE'=>'dse','MH01_MANUAL_HANDLING'=>'manual_handling','LW01_LONE_WORKING'=>'lone_working','WAH01_WORK_AT_HEIGHT'=>'work_at_height','YW01_YOUNG_WORKERS'=>'young_workers','CT01_CONTRACTORS'=>'contractors','DRV01_DRIVING'=>'driving_for_work'];if(isset($flags[$k]))return$c->hasRiskFlag($flags[$k]);if($k==='W01_WELFARE')return$c->nonHomeWorkplace()||$p['premises_responsibility']!=='no';if($k==='W02_WORK_EQUIPMENT')return$c->nonHomeWorkplace()||$c->hasRiskFlag('machinery');return true;}public function resolveQuestionText(ApplicabilityContext $c,array $q):string{if($q['question_key']!=='M02_POLICY')return$q['question_text'];$v=json_decode($q['variant_json']??'[]',true);return $v[in_array($c->profile['employee_band'],['5_9','10_49','50_249','250_plus'],true)?'5_plus':'under_5']??$q['question_text'];}}
